//! The Rust-export drift probe (#652): an actor generated by
//! `pulsar_script_codegen` (see `build.rs`), compiled against
//! `pulsar_game::lifecycle::NativeActor` and driven through the real tick loop.

#![cfg(test)]

mod generated {
    // The generated file is an `events.rs`: it names this crate as
    // `pulsar_game` and may leave helpers unused.
    #![allow(dead_code, unused_imports)]
    include!(concat!(env!("OUT_DIR"), "/export_probe_actor.rs"));
}

use crate::blueprint_codegen_drift::{
    REFERENCE_BEGIN_PLAY_SIGNATURE, REFERENCE_END_PLAY_SIGNATURE, REFERENCE_IMPL_LINE,
    REFERENCE_TICK_SIGNATURE,
};

const SOURCE: &str = include_str!(concat!(env!("OUT_DIR"), "/export_probe_actor.rs"));

/// THE drift assertion (#652): the emitted `impl NativeActor` must name the
/// trait by its full path with signatures byte-identical to the reference twin
/// compiled against the real trait, and the emission may not name any crate
/// the graph does not provide. (That it compiles at all, above, is the
/// stronger half.)
#[test]
fn emitted_actor_signatures_match_the_native_actor_trait() {
    assert!(
        SOURCE.contains(REFERENCE_IMPL_LINE),
        "the emitted impl drifted: it must be `{REFERENCE_IMPL_LINE}` ... (a fully qualified path, not the prelude's `Actor`)"
    );
    assert!(
        SOURCE.contains(REFERENCE_TICK_SIGNATURE),
        "the emitted NativeActor::tick drifted (expected `{REFERENCE_TICK_SIGNATURE}`)"
    );
    assert!(
        SOURCE.contains(REFERENCE_BEGIN_PLAY_SIGNATURE),
        "the emitted NativeActor::begin_play drifted from the trait"
    );
    assert!(
        SOURCE.contains(REFERENCE_END_PLAY_SIGNATURE),
        "the emitted NativeActor::end_play drifted from the trait"
    );
    assert!(
        !SOURCE.contains("impl Actor for") && !SOURCE.contains("pulsar_scenedb"),
        "the emission must not depend on SceneDB's `Actor`"
    );
    assert!(
        !SOURCE.contains("GameTime"),
        "no `GameTime` may be emitted: the script reads time from its own clock"
    );
    assert!(
        !SOURCE.contains("gamma_core"),
        "emitted code names `gamma_core`, which the graph does not provide"
    );
}

/// The generated actor runs on the real tick loop: a waiting `begin_play`
/// resumes on a later tick and `tick` runs once per tick, per actor.
#[test]
fn the_generated_actor_registers_and_ticks_through_the_real_tick_loop() {
    use crate::prelude::*;

    let mut game = crate::tick::TickLoop::new(pulsar_core::TickMode::default(), 0);
    game.register_native_actor(generated::ExportProbe::new());
    game.register_native_actor(generated::ExportProbe::new());
    for _ in 0..3 {
        game.tick_once();
    }
    // The session end runs `end_play` on both, through the lifecycle.
    game.end_session();
}

#[test]
fn a_clone_is_a_fresh_actor() {
    let actor = generated::ExportProbe::new();
    let _clone = actor.clone();
}
